pub struct DirectFileDependency {
    pub consumer_file: FilePath,
    pub provider_file: FilePath,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct DirectFileDependencyDedupBuild {
    pub providers_by_consumer: Rc<HashMap<FilePath, Rc<BTreeSet<String>>>>,
    pub edges_first_seen: Rc<Vec<Rc<DirectFileDependency>>>,
}

pub fn direct_file_dependency_from_provenance(
    provenance: Rc<CrossFileBindingProvenance>,
) -> Rc<DirectFileDependency> {
    Rc::new(DirectFileDependency {
        consumer_file: provenance.consumer_file.clone(),
        provider_file: provenance.provider_file.clone(),
    })
}

pub fn direct_file_dependency_dedup_step(
    acc: Rc<DirectFileDependencyDedupBuild>,
    provenance: Rc<CrossFileBindingProvenance>,
) -> Rc<DirectFileDependencyDedupBuild> {
    {
        let edge = direct_file_dependency_from_provenance(provenance.clone());
        if (edge.consumer_file.clone() == edge.provider_file.clone()) {
            acc.clone()
        } else {
            match v1_rt::map_get(
                &acc.providers_by_consumer.clone(),
                edge.consumer_file.clone(),
            ) {
                std::option::Option::None => Rc::new(DirectFileDependencyDedupBuild {
                    providers_by_consumer: v1_rt::rc_map_insert(
                        acc.providers_by_consumer.clone(),
                        edge.consumer_file.clone(),
                        v1_rt::rc_set_insert(
                            v1_rt::rc_empty_set::<_>(),
                            edge.provider_file.clone(),
                        ),
                    ),
                    edges_first_seen: v1_rt::concat(
                        Rc::new(vec![edge.clone()]),
                        acc.edges_first_seen.clone(),
                    ),
                }),
                Some(existing_providers) => {
                    if v1_rt::set_contains(&existing_providers, edge.provider_file.clone()) {
                        acc.clone()
                    } else {
                        Rc::new(DirectFileDependencyDedupBuild {
                            providers_by_consumer: v1_rt::rc_map_insert(
                                acc.providers_by_consumer.clone(),
                                edge.consumer_file.clone(),
                                v1_rt::rc_set_insert(
                                    existing_providers.clone(),
                                    edge.provider_file.clone(),
                                ),
                            ),
                            edges_first_seen: v1_rt::concat(
                                Rc::new(vec![edge.clone()]),
                                acc.edges_first_seen.clone(),
                            ),
                        })
                    }
                }
            }
        }
    }
}

pub fn provider_files_for_consumer_file(
    provenances: Rc<Vec<Rc<CrossFileBindingProvenance>>>,
    consumer_file: String,
) -> Rc<Vec<String>> {
    Rc::new({
        let mut __result = Vec::new();
        for edge in v1_rt::reverse(
            provenances
                .iter()
                .cloned()
                .fold(
                    Rc::new(DirectFileDependencyDedupBuild {
                        providers_by_consumer: v1_rt::rc_empty_map::<String, Rc<BTreeSet<String>>>(
                        ),
                        edges_first_seen: Rc::new(vec![]),
                    }),
                    |acc: Rc<DirectFileDependencyDedupBuild>,
                     provenance: Rc<CrossFileBindingProvenance>| {
                        match (provenance.consumer_file.clone() == consumer_file.clone()) {
                            true => {
                                direct_file_dependency_dedup_step(acc.clone(), provenance.clone())
                            }
                            false => acc.clone(),
                        }
                    },
                )
                .edges_first_seen
                .clone(),
        )
        .iter()
        .cloned()
        {
            __result.push(edge.provider_file.clone());
        }
        __result
    })
}

pub fn direct_file_dependencies_from_provenances(
    provenances: Rc<Vec<Rc<CrossFileBindingProvenance>>>,
) -> Rc<Vec<Rc<DirectFileDependency>>> {
    v1_rt::reverse(
        provenances
            .iter()
            .cloned()
            .fold(
                Rc::new(DirectFileDependencyDedupBuild {
                    providers_by_consumer: v1_rt::rc_empty_map::<String, Rc<BTreeSet<String>>>(),
                    edges_first_seen: Rc::new(vec![]),
                }),
                |acc: Rc<DirectFileDependencyDedupBuild>,
                 provenance: Rc<CrossFileBindingProvenance>| {
                    direct_file_dependency_dedup_step(acc, provenance.clone())
                },
            )
            .edges_first_seen
            .clone(),
    )
}

