pub fn section13_population_law_id_eq(
    left: Section13PopulationLawId,
    right: Section13PopulationLawId,
) -> bool {
    match left.clone() {
        Section13PopulationLawId::Section13StructuralVisibility => match right.clone() {
            Section13PopulationLawId::Section13StructuralVisibility => true,
            _ => false,
        },
        Section13PopulationLawId::Section13SiblingArmExclusion => match right.clone() {
            Section13PopulationLawId::Section13SiblingArmExclusion => true,
            _ => false,
        },
        Section13PopulationLawId::Section13LexicalEnclosure => match right.clone() {
            Section13PopulationLawId::Section13LexicalEnclosure => true,
            _ => false,
        },
        Section13PopulationLawId::Section13SourceOrderGate => match right.clone() {
            Section13PopulationLawId::Section13SourceOrderGate => true,
            _ => false,
        },
        Section13PopulationLawId::Section13DistinctIdentityAmbiguity => match right.clone() {
            Section13PopulationLawId::Section13DistinctIdentityAmbiguity => true,
            _ => false,
        },
        Section13PopulationLawId::Section13RepeatedDiscoverySameIdentityCollapse => {
            match right.clone() {
                Section13PopulationLawId::Section13RepeatedDiscoverySameIdentityCollapse => true,
                _ => false,
            }
        }
    }
}

pub fn section13_module_path_is_symbolic(module_path: String) -> bool {
    {
        let path = module_path.clone();
        (!v1_rt::string_contains(&path, "/".to_string())
            && !v1_rt::string_contains(&path, ".dag".to_string()))
    }
}

pub fn section13_roster_has_law(
    rows: Rc<Vec<Rc<Section13PopulationLawRosterRow>>>,
    law: Section13PopulationLawId,
) -> bool {
    {
        let mut __found = false;
        for row in rows.iter().cloned() {
            if section13_population_law_id_eq(row.law.clone(), law.clone()) {
                __found = true;
                break;
            }
        }
        __found
    }
}

pub fn section13_roster_covers_all_laws(
    rows: Rc<Vec<Rc<Section13PopulationLawRosterRow>>>,
) -> bool {
    (((((section13_roster_has_law(
        rows.clone(),
        Section13PopulationLawId::Section13StructuralVisibility,
    ) && section13_roster_has_law(
        rows.clone(),
        Section13PopulationLawId::Section13SiblingArmExclusion,
    )) && section13_roster_has_law(
        rows.clone(),
        Section13PopulationLawId::Section13LexicalEnclosure,
    )) && section13_roster_has_law(
        rows.clone(),
        Section13PopulationLawId::Section13SourceOrderGate,
    )) && section13_roster_has_law(
        rows.clone(),
        Section13PopulationLawId::Section13DistinctIdentityAmbiguity,
    )) && section13_roster_has_law(
        rows.clone(),
        Section13PopulationLawId::Section13RepeatedDiscoverySameIdentityCollapse,
    ))
}

pub fn section13_roster_has_duplicate_law(
    rows: Rc<Vec<Rc<Section13PopulationLawRosterRow>>>,
) -> bool {
    rows.clone().iter().cloned().fold(
        false,
        |found: bool, row: Rc<Section13PopulationLawRosterRow>| match found {
            true => true,
            false => {
                (rows.iter().cloned().fold(
                    0,
                    |count: i64, other: Rc<Section13PopulationLawRosterRow>| {
                        match section13_population_law_id_eq(row.law.clone(), other.law.clone()) {
                            true => (count.clone() + 1),
                            false => count.clone(),
                        }
                    },
                ) > 1)
            }
        },
    )
}

pub fn section13_first_duplicate_law(
    rows: Rc<Vec<Rc<Section13PopulationLawRosterRow>>>,
) -> Option<Section13PopulationLawId> {
    rows.clone().iter().cloned().fold(
        std::option::Option::None,
        |found: _, row: Rc<Section13PopulationLawRosterRow>| match found.clone() {
            Some(_) => found.clone(),
            std::option::Option::None => {
                if (rows.iter().cloned().fold(
                    0,
                    |count: i64, other: Rc<Section13PopulationLawRosterRow>| {
                        match section13_population_law_id_eq(row.law.clone(), other.law.clone()) {
                            true => (count.clone() + 1),
                            false => count.clone(),
                        }
                    },
                ) > 1)
                {
                    Some(row.law.clone())
                } else {
                    std::option::Option::None
                }
            }
        },
    )
}

pub fn section13_first_uncovered_law(
    rows: Rc<Vec<Rc<Section13PopulationLawRosterRow>>>,
) -> Option<Section13PopulationLawId> {
    if !section13_roster_has_law(
        rows.clone(),
        Section13PopulationLawId::Section13StructuralVisibility,
    ) {
        Some(Section13PopulationLawId::Section13StructuralVisibility)
    } else {
        if !section13_roster_has_law(
            rows.clone(),
            Section13PopulationLawId::Section13SiblingArmExclusion,
        ) {
            Some(Section13PopulationLawId::Section13SiblingArmExclusion)
        } else {
            if !section13_roster_has_law(
                rows.clone(),
                Section13PopulationLawId::Section13LexicalEnclosure,
            ) {
                Some(Section13PopulationLawId::Section13LexicalEnclosure)
            } else {
                if !section13_roster_has_law(
                    rows.clone(),
                    Section13PopulationLawId::Section13SourceOrderGate,
                ) {
                    Some(Section13PopulationLawId::Section13SourceOrderGate)
                } else {
                    if !section13_roster_has_law(
                        rows.clone(),
                        Section13PopulationLawId::Section13DistinctIdentityAmbiguity,
                    ) {
                        Some(Section13PopulationLawId::Section13DistinctIdentityAmbiguity)
                    } else {
                        if !section13_roster_has_law(rows.clone(), Section13PopulationLawId::Section13RepeatedDiscoverySameIdentityCollapse) {
                            Some(Section13PopulationLawId::Section13RepeatedDiscoverySameIdentityCollapse)
                        } else {
                            std::option::Option::None
                        }
                    }
                }
            }
        }
    }
}

pub fn section13_observation_joins_receipt(
    receipt: Rc<DeclarationRef>,
    observations: Rc<Vec<Rc<Section13ExactHeadExecutionObservation>>>,
    required_head: String,
) -> Option<bool> {
    observations
        .iter()
        .cloned()
        .fold(
            std::option::Option::None,
            |found: _, observation: _| match found.clone() {
                Some(_) => found.clone(),
                std::option::Option::None => {
                    if (crate::std_decl_ref::declaration_ref_eq(
                        observation.declaration.clone(),
                        receipt.clone(),
                    ) && (observation.head.clone() == required_head.clone()))
                    {
                        Some(observation.passed.clone())
                    } else {
                        std::option::Option::None
                    }
                }
            },
        )
}

pub fn section13_adjudicate_row(
    row: Rc<Section13PopulationLawRosterRow>,
    observations: Rc<Vec<Rc<Section13ExactHeadExecutionObservation>>>,
    required_head: String,
) -> Rc<Section13PopulationLawRosterVerdict> {
    match (*row.evidence.clone()).clone() {
    Section13PopulationLawEvidence::Section13PopulationLawExecuting { receipt: receipt, .. } => if !section13_module_path_is_symbolic(receipt.module_path.clone()) {
        Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterRefusedPositionalModulePath {
    receipt: receipt.clone(),
})
    } else {
        match section13_observation_joins_receipt(receipt.clone(), observations.clone(), required_head.clone()) {
    std::option::Option::None => Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterRefusedMissingObservation {
    receipt: receipt.clone(),
}),
    Some(false) => Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterRefusedFailedOrStaleObservation {
    receipt: receipt.clone(),
}),
    Some(true) => Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterHolds),
}
    },
    Section13PopulationLawEvidence::Section13PopulationLawDeferredProductionOccurrenceCollectorMissing { dissolve_on: dissolve_on, .. } => match dissolve_on.clone() {
    Some(trigger) => if section13_module_path_is_symbolic(trigger.module_path.clone()) {
        Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterHolds)
    } else {
        Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterRefusedPositionalModulePath {
    receipt: trigger.clone(),
})
    },
    std::option::Option::None => Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterRefusedDeferredMissingTrigger),
},
}
}

pub fn section13_population_law_roster_adjudicate(
    observations: Rc<Vec<Rc<Section13ExactHeadExecutionObservation>>>,
    required_head: String,
) -> Rc<Section13PopulationLawRosterVerdict> {
    {
        let rows = section13_population_law_roster();
        match section13_first_duplicate_law(rows.clone()) {
    Some(law) => Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterRefusedDuplicateLaw {
    law: law.clone(),
}),
    std::option::Option::None => match section13_first_uncovered_law(rows.clone()) {
    Some(law) => Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterRefusedUncoveredLaw {
    law: law.clone(),
}),
    std::option::Option::None => rows.iter().cloned().fold(Rc::new(Section13PopulationLawRosterVerdict::Section13PopulationLawRosterHolds), |verdict: Rc<Section13PopulationLawRosterVerdict>, row: Rc<Section13PopulationLawRosterRow>| match (*verdict.clone()).clone() {
    Section13PopulationLawRosterVerdict::Section13PopulationLawRosterHolds => section13_adjudicate_row(row.clone(), observations.clone(), required_head.clone()),
    _ => verdict.clone(),
}),
},
}
    }
}

pub fn section13_population_law_roster_denominator_holds(
    observations: Rc<Vec<Rc<Section13ExactHeadExecutionObservation>>>,
    required_head: String,
) -> bool {
    match (*section13_population_law_roster_adjudicate(observations.clone(), required_head.clone()))
        .clone()
    {
        Section13PopulationLawRosterVerdict::Section13PopulationLawRosterHolds => true,
        _ => false,
    }
}

pub fn section13_module_path_is_symbolic_dissolve_on() -> Rc<DissolutionCondition> {
    thread_local! {
        static CACHED: Rc<DissolutionCondition> = {
            crate::std_dissolution::unbound_dissolution("feature:module-path-qualified-name — DISSOLVE-ON: DeclarationRef.module_path / OccurrenceModulePathRow.module_path become v2.std.qualified_name.QualifiedName (same trigger as occurrence_module_path_convergence_note / std.observation observation_segment_grounding_note); then positional file-path inhabitance is unwritable, this string-grep oracle deletes, and section13_adjudicate_row stops calling i".to_string())
        };
    }
    CACHED.with(|c: &Rc<DissolutionCondition>| c.clone())
}

